-- Generated by nook. Review before applying; create a new migration to change history.

CREATE TABLE "apps" (
  "id" INTEGER PRIMARY KEY CONSTRAINT "app_id_positive" CHECK (id > 0),
  "name" TEXT NOT NULL CHECK (length("name") > 0),
  "type" TEXT NOT NULL,
  "last_modified" INTEGER NOT NULL DEFAULT 0,
  "price_change_number" INTEGER NOT NULL DEFAULT 0,
  "updated_at" TEXT NOT NULL,
  "name_fold" TEXT NOT NULL DEFAULT ''
) STRICT;

CREATE INDEX "apps_name_fold" ON "apps" ("name_fold");

CREATE TABLE "deliveries" (
  "id" TEXT PRIMARY KEY NOT NULL CHECK (length("id") > 0) CHECK (length("id") <= 24),
  "event_id" TEXT NOT NULL UNIQUE REFERENCES "events" ("id"),
  "destination_id" TEXT NOT NULL CHECK (length("destination_id") > 0),
  "status" TEXT NOT NULL DEFAULT 'pending' CHECK ("status" IN ('pending', 'sending', 'retry', 'sent', 'dead', 'cancelled')),
  "attempt_count" INTEGER NOT NULL DEFAULT 0 CONSTRAINT "delivery_attempt_count_nonnegative" CHECK (attempt_count >= 0),
  "next_attempt_at" TEXT NOT NULL,
  "message_id" TEXT NOT NULL DEFAULT '',
  "last_error" TEXT NOT NULL DEFAULT '',
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL
) STRICT;

CREATE INDEX "deliveries_status_next_attempt_at" ON "deliveries" ("status", "next_attempt_at");

CREATE TABLE "events" (
  "id" TEXT PRIMARY KEY NOT NULL CHECK (length("id") > 0) CHECK (length("id") <= 24),
  "rule_id" TEXT NOT NULL REFERENCES "rules" ("id"),
  "observation_id" TEXT NOT NULL REFERENCES "observations" ("id"),
  "payload" TEXT NOT NULL,
  "created_at" TEXT NOT NULL
) STRICT;

CREATE UNIQUE INDEX "events_rule_id_observation_id" ON "events" ("rule_id", "observation_id");

CREATE TABLE "free_deliveries" (
  "id" TEXT PRIMARY KEY NOT NULL CHECK (length("id") > 0) CHECK (length("id") <= 24),
  "offer_id" TEXT NOT NULL CHECK (length("offer_id") > 0),
  "subscription_id" TEXT NOT NULL CHECK (length("subscription_id") > 0),
  "offer_generation" INTEGER NOT NULL DEFAULT 1 CONSTRAINT "freedelivery_offer_generation_positive" CHECK (offer_generation > 0),
  "destination_kind" TEXT NOT NULL CHECK ("destination_kind" IN ('dm', 'channel')),
  "destination_id" TEXT NOT NULL CHECK (length("destination_id") > 0),
  "payload" TEXT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'pending' CHECK ("status" IN ('pending', 'sending', 'retry', 'sent', 'dead', 'cancelled')),
  "attempt_count" INTEGER NOT NULL DEFAULT 0 CONSTRAINT "freedelivery_attempt_count_nonnegative" CHECK (attempt_count >= 0),
  "next_attempt_at" TEXT NOT NULL,
  "message_id" TEXT NOT NULL DEFAULT '',
  "last_error" TEXT NOT NULL DEFAULT '',
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL
) STRICT;

CREATE UNIQUE INDEX "free_deliveries_offer_id_offer_generation_subscription_id" ON "free_deliveries" ("offer_id", "offer_generation", "subscription_id");

CREATE INDEX "free_deliveries_status_next_attempt_at" ON "free_deliveries" ("status", "next_attempt_at");

CREATE TABLE "free_monitors" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "checked_at" TEXT,
  "next_check_at" TEXT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'not checked',
  "problems" TEXT NOT NULL DEFAULT '[]',
  "failures" INTEGER NOT NULL DEFAULT 0
) STRICT;

CREATE TABLE "free_offers" (
  "id" TEXT PRIMARY KEY NOT NULL CHECK (length("id") > 0) CHECK (length("id") <= 24),
  "identity" TEXT NOT NULL UNIQUE,
  "source" TEXT NOT NULL CHECK (length("source") > 0),
  "payload" TEXT NOT NULL,
  "eligible" INTEGER NOT NULL DEFAULT 0 CHECK ("eligible" IN (0, 1)),
  "closed" INTEGER NOT NULL DEFAULT 0 CHECK ("closed" IN (0, 1)),
  "generation" INTEGER NOT NULL DEFAULT 1 CONSTRAINT "freeoffer_generation_positive" CHECK (generation > 0),
  "first_seen_at" TEXT NOT NULL,
  "last_seen_at" TEXT NOT NULL
) STRICT;

CREATE INDEX "free_offers_source_eligible" ON "free_offers" ("source", "eligible");

CREATE TABLE "free_subscriptions" (
  "id" TEXT PRIMARY KEY NOT NULL CHECK (length("id") > 0) CHECK (length("id") <= 24),
  "scope" TEXT NOT NULL CHECK (length("scope") > 0),
  "source" TEXT NOT NULL CHECK (length("source") > 0),
  "destination_kind" TEXT NOT NULL CHECK ("destination_kind" IN ('dm', 'channel')),
  "destination_id" TEXT NOT NULL CHECK (length("destination_id") > 0),
  "managed_by" TEXT NOT NULL CHECK (length("managed_by") > 0),
  "enabled" INTEGER NOT NULL DEFAULT 1 CHECK ("enabled" IN (0, 1)),
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL
) STRICT;

CREATE UNIQUE INDEX "free_subscriptions_scope_source" ON "free_subscriptions" ("scope", "source");

CREATE INDEX "free_subscriptions_source_enabled" ON "free_subscriptions" ("source", "enabled");

CREATE TABLE "observations" (
  "id" TEXT PRIMARY KEY NOT NULL CHECK (length("id") > 0) CHECK (length("id") <= 24),
  "target_id" TEXT NOT NULL REFERENCES "targets" ("id"),
  "observed_at" TEXT NOT NULL,
  "price" TEXT NOT NULL
) STRICT;

CREATE INDEX "observations_observed_at" ON "observations" ("observed_at");

CREATE INDEX "observations_target_id_observed_at" ON "observations" ("target_id", "observed_at");

CREATE TABLE "rules" (
  "id" TEXT PRIMARY KEY NOT NULL CHECK (length("id") > 0) CHECK (length("id") <= 24),
  "target_id" TEXT NOT NULL REFERENCES "targets" ("id"),
  "owner_id" TEXT NOT NULL CHECK (length("owner_id") > 0),
  "request_id" TEXT UNIQUE,
  "condition" TEXT NOT NULL CHECK ("condition" IN ('any_sale', 'sale_under_budget')),
  "budget_minor" INTEGER CONSTRAINT "rule_budget_minor_nonnegative" CHECK (budget_minor >= 0),
  "budget_currency" TEXT NOT NULL DEFAULT '',
  "recurring" INTEGER NOT NULL DEFAULT 0 CHECK ("recurring" IN (0, 1)),
  "enabled" INTEGER NOT NULL DEFAULT 1 CHECK ("enabled" IN (0, 1)),
  "latched" INTEGER NOT NULL DEFAULT 0 CHECK ("latched" IN (0, 1)),
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  CONSTRAINT "rule_budget" CHECK ((condition = 'any_sale' AND budget_minor IS NULL AND budget_currency = '') OR (condition = 'sale_under_budget' AND budget_minor IS NOT NULL AND budget_minor >= 0 AND length(budget_currency) = 3 AND budget_currency GLOB '[A-Z][A-Z][A-Z]'))
) STRICT;

CREATE INDEX "rules_owner_id_enabled" ON "rules" ("owner_id", "enabled");

CREATE UNIQUE INDEX "rules_owner_id_target_id_condition" ON "rules" ("owner_id", "target_id", "condition") WHERE enabled = 1;

CREATE INDEX "rules_target_id_enabled" ON "rules" ("target_id", "enabled");

CREATE TABLE "targets" (
  "id" TEXT PRIMARY KEY NOT NULL CHECK (length("id") > 0) CHECK (length("id") <= 24),
  "app_id" INTEGER NOT NULL REFERENCES "apps" ("id"),
  "country" TEXT NOT NULL CHECK (length("country") <= 2),
  "next_due_at" TEXT NOT NULL,
  "last_observed_at" TEXT,
  "failure_count" INTEGER NOT NULL DEFAULT 0 CONSTRAINT "target_failure_count_nonnegative" CHECK (failure_count >= 0),
  "last_error" TEXT NOT NULL DEFAULT '',
  CONSTRAINT "target_country" CHECK (length(country) = 2 AND country GLOB '[A-Z][A-Z]')
) STRICT;

CREATE UNIQUE INDEX "targets_app_id_country" ON "targets" ("app_id", "country");

CREATE INDEX "targets_next_due_at" ON "targets" ("next_due_at");
